#include "native_agent_batch_46_60.hpp"
#include <algorithm>
#include <sstream>
namespace RawrXD::NativeBridge {
Result validateRunConfig(const RunConfig& c){if(!c.maxTasks||!c.maxArgs||!c.maxArgBytes||!c.maxOutputBytes||c.permittedTools.empty())return {false,{},"invalid execution limits or empty tool allowlist"};if(c.maxTasks>100000||c.maxOutputBytes>64*1024*1024)return {false,{},"limits exceed safety cap"};return {true,"valid",{}};}
Result preflightTasks(const std::vector<Task>& tasks,const RunConfig& c){auto v=validateRunConfig(c);if(!v.ok)return v;if(tasks.size()>c.maxTasks)return {false,{},"task limit exceeded"};v=DependencyGraph::validate(tasks);if(!v.ok)return v;for(auto& t:tasks){if(!c.permittedTools.count(t.tool))return {false,{},"tool not permitted: "+t.tool};v=validateTaskArguments(t,c.maxArgs,c.maxArgBytes);if(!v.ok)return v;}return {true,"preflight passed",{}};}
std::vector<std::string> rootsOf(const std::vector<Task>& tasks,std::string& err){auto v=DependencyGraph::validate(tasks);if(!v.ok){err=v.error;return {};}std::vector<std::string> out;for(auto& t:tasks)if(t.dependencies.empty())out.push_back(t.id);std::sort(out.begin(),out.end());return out;}
std::vector<std::string> dependentsOf(const std::vector<Task>& tasks,const std::string& id,std::string& err){auto v=DependencyGraph::validate(tasks);if(!v.ok){err=v.error;return {};}bool found=false;for(auto& t:tasks)found|=t.id==id;if(!found){err="unknown task";return {};}std::set<std::string> reached{id};bool changed;do{changed=false;for(auto& t:tasks)for(auto& dep:t.dependencies)if(reached.count(dep)&&reached.insert(t.id).second)changed=true;}while(changed);reached.erase(id);return {reached.begin(),reached.end()};}
std::vector<std::string> terminalFailures(const std::vector<ExecutionReceipt>& receipts){std::vector<std::string> out;for(auto& r:receipts)if(!r.success)out.push_back(r.taskId);std::sort(out.begin(),out.end());out.erase(std::unique(out.begin(),out.end()),out.end());return out;}
Result validateNoDuplicateReceipts(const std::vector<ExecutionReceipt>& receipts){std::set<std::string> ids;for(auto& r:receipts)if(r.taskId.empty()||!ids.insert(r.taskId).second)return {false,{},"empty or duplicate receipt id"};return {true,"unique",{}};}
Result validateReceiptsAgainstTasks(const std::vector<Task>& tasks,const std::vector<ExecutionReceipt>& receipts){auto v=DependencyGraph::validate(tasks);if(!v.ok)return v;v=validateNoDuplicateReceipts(receipts);if(!v.ok)return v;std::map<std::string,const Task*> known;for(auto& t:tasks)known[t.id]=&t;for(auto& r:receipts){auto it=known.find(r.taskId);if(it==known.end())return {false,{},"unknown receipt task"};if(r.tool!=it->second->tool)return {false,{},"receipt tool mismatch"};if(r.inputHash!=taskFingerprint(*it->second))return {false,{},"receipt input mismatch"};}return {true,"receipts match tasks",{}};}
std::string escapeLogField(const std::string& s){std::string out;for(unsigned char c:s){if(c=='\\')out+="\\\\";else if(c=='\n')out+="\\n";else if(c=='\r')out+="\\r";else if(c=='\t')out+="\\t";else if(c<32)out+='?';else out+=static_cast<char>(c);}return out;}
std::string diagnosticLine(const ExecutionReceipt& r){return escapeLogField(r.taskId)+"\t"+escapeLogField(r.tool)+"\t"+(r.success?"PASS":"FAIL")+"\t"+escapeLogField(r.error);}
std::string renderExecutionReport(const std::vector<Task>& tasks,const std::vector<ExecutionReceipt>& receipts){std::ostringstream o;auto s=summarize(receipts,tasks.size());o<<"planned="<<tasks.size()<<" succeeded="<<s.succeeded<<" failed="<<s.failed<<" skipped="<<s.skipped<<" complete="<<(s.complete?"true":"false")<<'\n';for(auto& r:receipts)o<<diagnosticLine(r)<<'\n';return o.str();}
Result verifyExpectedFingerprints(const std::vector<ExecutionReceipt>& receipts,const std::map<std::string,std::string>& expected){std::map<std::string,std::string> got;for(auto& r:receipts)if(!got.emplace(r.taskId,r.outputHash).second)return {false,{},"duplicate receipt"};for(auto& [id,hash]:expected){auto it=got.find(id);if(it==got.end())return {false,{},"missing receipt: "+id};if(it->second!=hash)return {false,{},"output fingerprint mismatch: "+id};}return {true,"expected fingerprints match",{}};}
Result guardedRun(const Task& task,const RunConfig& config,const ControlledTools& tools,const std::atomic<bool>& cancel,ExecutionReceipt& receipt){auto v=validateRunConfig(config);if(!v.ok)return v;if(!config.permittedTools.count(task.tool))return {false,{},"tool not permitted"};v=validateTaskArguments(task,config.maxArgs,config.maxArgBytes);if(!v.ok)return v;if(cancel.load())return {false,{},"cancelled"};auto r=runChecked(task,tools,cancel,receipt);auto check=validateOutput(r,config.maxOutputBytes);if(!check.ok){receipt.success=false;receipt.error=check.error;return check;}return r;}
Result guardedPlanRun(const std::vector<Task>& tasks,const RunConfig& config,const ControlledTools& tools,const std::atomic<bool>& cancel,std::vector<ExecutionReceipt>& receipts){auto v=preflightTasks(tasks,config);if(!v.ok)return v;std::string err;auto order=DependencyGraph::order(tasks,err);if(!err.empty())return {false,{},err};std::map<std::string,const Task*> index;for(auto& t:tasks)index[t.id]=&t;std::map<std::string,bool> ok;bool all=true;for(auto& id:order){if(cancel.load())return {false,{},"cancelled"};const auto& t=*index.at(id);bool blocked=false;for(auto& dep:t.dependencies)if(!ok[dep])blocked=true;ExecutionReceipt rec;rec.taskId=t.id;rec.tool=t.tool;rec.inputHash=taskFingerprint(t);if(blocked){rec.error="dependency failed";rec.success=false;receipts.push_back(rec);ok[id]=false;all=false;continue;}auto result=guardedRun(t,config,tools,cancel,rec);receipts.push_back(rec);ok[id]=result.ok;all&=result.ok;}return all?Result{true,"all tasks succeeded",{}}:Result{false,{},"one or more tasks failed"};}
std::vector<std::string> pendingTaskIds(const std::vector<Task>& tasks,const std::vector<ExecutionReceipt>& receipts){std::set<std::string> done;for(auto& r:receipts)done.insert(r.taskId);std::vector<std::string> out;for(auto& t:tasks)if(!done.count(t.id))out.push_back(t.id);std::sort(out.begin(),out.end());return out;}
Result verifyCompletedPlan(const std::vector<Task>& tasks,const std::vector<ExecutionReceipt>& receipts){auto v=validateReceiptsAgainstTasks(tasks,receipts);if(!v.ok)return v;if(!pendingTaskIds(tasks,receipts).empty())return {false,{},"incomplete task receipts"};for(auto& r:receipts)if(!r.success)return {false,{},"failed task: "+r.taskId};return {true,"plan complete",{}};}
}
